icash_claim_operation:
CREATE OR REPLACE FUNCTION public.icash_claim_operation(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select account_id into a from public.icash_operation_spend where operation_key=p_operation;
 if a is not null and not public.icash_seller_response_operation_allowed(a,p_operation) then return false;end if;
 return public.icash_claim_before_seller_response(p_operation);
end $function$

icash_claim_text_before_ai:
CREATE OR REPLACE FUNCTION public.icash_claim_text_before_ai(p_account uuid, p_message uuid, p_sender text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_text_messages;t public.icash_text_threads;r uuid;h integer;prop text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account;
 select * into t from public.icash_text_threads where id=m.thread_id and account_id=p_account;
 if t.id is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(t.recipient,74));
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account for update;
 if not found or m.state<>'ready' or m.direction<>'outgoing' then return null;end if;
 select * into t from public.icash_text_threads where id=m.thread_id and account_id=p_account for update;
 if not found or (t.paused and not (public.icash_manual_handoff_reply(p_account,t.id) and not exists(select 1 from public.icash_text_ai_jobs where outgoing_id=p_message and account_id=p_account))) or t.sender<>p_sender or not public.icash_sms_thread_review_current(p_account,t.id,true) then return null;end if;
 if not exists(select 1 from public.icash_text_senders where phone=t.sender and enabled) then return null;end if;
 if exists(select 1 from public.icash_text_suppressions where phone=t.recipient) then return null;end if;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;if not found then return null;end if;
 select s.snapshot->>'propertyId' into prop from public.icash_deal_files d join public.icash_screening_jobs s on s.id=d.screening_id and s.account_id=d.account_id where d.id=t.deal_id and d.account_id=p_account and d.stage not in ('cancelled','closed');
 if prop is null then return null;end if;
 if not public.icash_sms_outreach_window_current(p_account,t.id) then return null;end if;
 -- Human-authored API sends; automated generation/queueing is not enabled by this RPC.
 if cardinality(m.asset_ids)>0 and (select count(*) from public.icash_text_assets where id=any(m.asset_ids) and account_id=p_account and deal_id=t.deal_id and verified_until>now())<>cardinality(m.asset_ids) then return null;end if;
 if cardinality(m.asset_ids)>0 and (select jsonb_agg(url order by id) from public.icash_text_assets where id=any(m.asset_ids)) is distinct from m.attachments then return null;end if;
 r:=case when cardinality(m.asset_ids)>0 then t.mms_rate_id else t.sms_rate_id end;
 if not exists(select 1 from public.icash_operation_rates where id=r and operation=case when cardinality(m.asset_ids)>0 then 'mms_send' else 'sms_send' end and enabled and expires_at>now()) then return null;end if;
 perform public.icash_reserve_operation(p_account,'text:'||m.id,r,public.icash_sms_thread_dispatch_until(p_account,t.id));
 if not public.icash_claim_operation('text:'||m.id) then raise exception 'Text already dispatched';end if;
 update public.icash_text_messages set state='dispatching',updated_at=now() where id=m.id;
 return jsonb_build_object('from',t.sender,'to',t.recipient,'message',m.body,'attachments',m.attachments);
end $function$

icash_queue_seller_opener:
CREATE OR REPLACE FUNCTION public.icash_queue_seller_opener(p_account uuid, p_thread uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;d public.icash_deal_files;principal text;buyer_description text;address text;seller text;greeting text:='Hi, ';message_body text;message uuid;choice jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
perform 1 from public.icash_operating_budget where id=1 for update;
 if not public.icash_outreach_sms_current(p_account) then return null;end if;
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account and party='seller' and not paused and ai_mode='auto' and public.icash_sms_thread_review_current(p_account,id,false) for update;
 if not found or exists(select 1 from public.icash_seller_opener_assignments where thread_id=t.id)
  or exists(select 1 from public.icash_text_messages where thread_id=t.id and (state in ('ready','dispatching','needs_review') or created_at>now()-interval '1 day')) then return null;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true';
 if not found then return null;end if;
 select trim(i.principal),case when nullif(trim(i.company_name),'') is null then 'an individual HomeOffer Network investor' else 'an independent HomeOffer Network cash buyer' end into principal,buyer_description from public.icash_customer_identities i where i.account_id=p_account;
 address:=public.icash_conversation_street(d.terms->>'address');
 if coalesce(length(address),0)=0 or coalesce(length(principal),0)=0 then return null;end if;
 -- A property-record owner is not necessarily the person replying. Use only
 -- a strict self-introduction from this same contact after an actually sent text.
 -- Capture the FIRST name, never disclose terms.seller or another recorded owner.
 select substring(m.body from '^(?:[Tt]his is|[Mm]y name is|I''m|I am) ([A-Z][a-z]{1,24})(?:[ ''-][A-Z][a-z]{1,24}){0,2}[.!]?$') into seller
 from public.icash_text_messages m
 where m.thread_id=t.id and m.account_id=p_account and m.direction='incoming' and m.state='received'
 and m.body ~ '^(?:[Tt]his is|[Mm]y name is|I''m|I am) ([A-Z][a-z]{1,24})(?:[ ''-][A-Z][a-z]{1,24}){0,2}[.!]?$'
 and exists(select 1 from public.icash_text_messages sent where sent.thread_id=t.id and sent.account_id=p_account and sent.direction='outgoing' and sent.state in ('accepted','delivered') and sent.provider_id is not null and sent.created_at<m.created_at)
 order by m.created_at desc,m.id desc limit 1;
 if lower(seller) in ('interested','owner','selling','ready','not','yes','no') then seller:=null;end if;
 if seller is not null then greeting:='Hi '||seller||', ';end if;
 if t.seller_intake_id is not null and public.icash_seller_contact_evidence(p_account,d.screening_id,t.seller_intake_id,t.recipient) is not null then
  select split_part(trim(l.name),' ',1) into seller from public.icash_seller_intakes l where l.id=t.seller_intake_id and l.phone=t.recipient;
  if seller is null or seller !~ '^[A-Za-z][A-Za-z]{0,30}$' then seller:=null;end if;
  message_body:=public.icash_seller_recipient_opener(p_account,t.id,seller,principal,address);
  if message_body is null then return null;end if;
 else
  message_body:='Is this '||case when seller is null then '' else seller||', ' end||'the owner of '||address||'? I am reaching out about a possible cash offer.';
 end if;
 -- Retain the existing one-segment rate. Never silently truncate identity/address or bill extra segments.
 if length(message_body)>160 or message_body ~ '[^A-Za-z0-9 .,!?]' then return null;end if;
 choice:=public.icash_assign_seller_opener(p_account,t.id);
 if choice is null then return null;end if;
 if choice->>'context'='interest-v2' then
  message_body:=replace(replace(choice->>'body','{owner}',case when seller is null then '' else seller||', ' end||'the owner'),'{address}',address);
  -- Any invalid expansion rolls back the new assignment along with this call.
  if length(message_body)>160 or message_body ~ '[^A-Za-z0-9 .,!?]' then raise exception 'Seller experiment copy requires review';end if;
 end if;
 update public.icash_seller_opener_assignments a set body=message_body where a.thread_id=t.id and a.account_id=p_account and a.message_id is null;
 message:=public.icash_queue_text(p_account,t.id,t.id,message_body,'{}');
 insert into public.icash_sms_seller_openings(thread_id,account_id,owner_question_id) values(t.id,p_account,message);
 return message;
end $function$

